import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;class ContractTest{@Test void allSlotsReuseAndPlainPayloadIdentity()throws Exception{for(int kind=0;kind<3;kind++){Object q=TaskBinding.create(kind,1);assertTrue(TaskBinding.empty(assertThrows(Exception.class,()->TaskBinding.pop(q))),"prefilled storage still starts empty");Object a=kind==0?new String("x"):kind==1?Integer.valueOf(1000):TaskBinding.payload("x");Object b=kind==0?new String("y"):kind==1?Integer.valueOf(1001):TaskBinding.payload("y");TaskBinding.push(q,a);assertTrue(TaskBinding.full(assertThrows(Exception.class,()->TaskBinding.push(q,b))));assertSame(a,TaskBinding.pop(q));assertTrue(TaskBinding.empty(assertThrows(Exception.class,()->TaskBinding.pop(q))));TaskBinding.push(q,b);assertSame(b,TaskBinding.pop(q));}}}
